def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    # Count recent opponent behavior
    last = min(10, n)
    opp_defects = sum(1 for i in range(n - last, n) if opp(i) == 'D')
    my_defects = sum(1 for i in range(n - last, n) if me(i) == 'D')

    # Always defect in final few rounds to secure terminal payoff
    if n >= 96:
        return 'D'

    # If opponent has defected at all recently, punish hard
    if opp_defects > 0:
        # Tit-for-tat style: defect if last opponent defected, but occasionally forgive
        if opp(n - 1) == 'D':
            # Forgive once in a while if recent defections are low
            if opp_defects <= 1 and n > 20 and rng.random() < 0.15:
                return 'C'
            return 'D'
        else:
            return 'C'

    # Opponent has been cooperating recently. Exploit moderately.
    # Against pure cooperators, defect often to gain 5 vs 3 per round.
    if opp_defects == 0:
        if n < 5:
            return 'C'
        # Exploit with high probability but keep some cooperation to avoid
        # triggering retaliation from forgiving opponents.
        if n > 90:
            return 'D'
        if rng.random() < 0.65:
            return 'D'
        return 'C'

    return 'C'
